def get_tasks_on_machine_at_time(scope, machine_id, time):
    node = node_by_title(doc, f"{scope}: Task log")
    rows = table_rows(node)
    tasks = {}
    for idx, row in rows:
        t_time = int(row['time'])
        if t_time > time:
            break
        task_id = row['task']
        event = row['event']
        if event == 'start' and row['machine'] == machine_id:
            # find run time from submit row
            run_time = None
            for idx2, row2 in rows:
                if row2['task'] == task_id and row2['event'] == 'submit':
                    run_time = int(row2['run time'])
                    break
            tasks[task_id] = {'start': t_time, 'end': t_time + run_time}
        elif event == 'finish' and row['machine'] == machine_id:
            if task_id in tasks:
                del tasks[task_id]
        elif event == 'evict' and row['machine'] == machine_id:
            if task_id in tasks:
                del tasks[task_id]
        elif event == 'fail' and row['machine'] == machine_id:
             # All tasks on the machine fail. But this function is for a specific machine.
             # If the machine failed, it's not 'up'.
             pass
    return tasks

