    mach_rows = table_rows(node_mach)
    machines = {}
    for idx, row in mach_rows:
        machines[row['machine']] = {
            'cpu': int(row['CPU']),
            'mem': int(row['memory']),
            'fail': int(row['fails at']) if row['fails at'] != '-' else None,
            'return': int(row['returns at']) if row['returns at'] != '-' else None,
            'up': True,
            'tasks': {} # task_id -> {cpu, mem, priority, end_time}
        }

    node_log = node_by_title(doc, f"{scope}: Task log")
    log_rows = table_rows(node_log)

    for idx, row in log_rows:
        t_time = int(row['time'])
        if t_time > time:
            break

        task_id = row['task']
        event = row['event']

        if event == 'start':
            m_id = row['machine']
            td = task_details[task_id]
            machines[m_id]['tasks'][task_id] = td

        elif event == 'finish':
            m_id = row['machine']
            if task_id in machines[m_id]['tasks']:
                del machines[m_id]['tasks'][task_id]

        elif event == 'evict':
            m_id = row['machine']
            if task_id in machines[m_id]['tasks']:
                del machines[m_id]['tasks'][task_id]

        elif event == 'fail':
            m_id = row['machine']
            if m_id in machines:
                machines[m_id]['tasks'] = {}
                machines[m_id]['up'] = False

        for m_id, m_info in machines.items():
            if not m_info['up'] and m_info['return'] == t_time:
                m_info['up'] = True

    return machines

