def get_queue_at(chapter, time):
    task_log_node = node_by_title(doc, f"{chapter}: Task log")
    rows = table_rows(task_log_node)
    submitted = {}
    started = {}
    finished = {}

    for row_idx, row in rows:
        t_id = row['task']
        t_time = int(row['time'])
        if t_time > time:
            break
        if row['event'] == 'submit':
            submitted[t_id] = {
                'submit': t_time,
                'priority': int(row['priority']),
                'cpu': int(row['CPU']),
                'memory': int(row['memory']),
                'run_time': int(row['run time'])
            }
        elif row['event'] == 'start':
            started[t_id] = t_time
        elif row['event'] in ['finish', 'evict', 'fail']:
            finished[t_id] = t_time

    queue = []
    for t_id, info in submitted.items():
        if t_id not in started or (t_id in finished and finished[t_id] <= time):
            # The logic here is slightly off for restarts.
            # A task is in the queue if it has been submitted and (has not started OR was most recently stopped).
            pass

    # Let's do this more carefully.
    queue_tasks = {}
    for row_idx, row in rows:
        t_id = row['task']
        t_time = int(row['time'])
        if t_time > time:
            break
        if row['event'] == 'submit':
            queue_tasks[t_id] = {
                'submit': t_time,
                'priority': int(row['priority']),
                'cpu': int(row['CPU']),
                'memory': int(row['memory']),
                'run_time': int(row['run time']),
                'status': 'waiting'
            }
        elif row['event'] == 'start':
            if t_id in queue_tasks:
                queue_tasks[t_id]['status'] = 'running'
        elif row['event'] in ['finish', 'evict', 'fail']:
            if t_id in queue_tasks:
                if row['event'] == 'finish':
                    queue_tasks[t_id]['status'] = 'finished'
                else:
                    queue_tasks[t_id]['status'] = 'waiting'

    return {t_id: info for t_id, info in queue_tasks.items() if info['status'] == 'waiting'}

