# Create a helper to track machine resources
class Machine:
    def __init__(self, data):
        self.id = data['machine']
        self.cpu_cap = int(data['CPU'])
        self.mem_cap = int(data['memory'])
        self.cpu_used = 0
        self.mem_used = 0
        self.fail_at = int(data['fails at']) if data['fails at'] != '-' else None
        self.return_at = int(data['returns at']) if data['returns at'] != '-' else None
        self.is_up = True

    def can_fit(self, cpu, mem):
        return self.is_up and (self.cpu_cap - self.cpu_used >= cpu) and (self.mem_cap - self.mem_used >= mem)

    def allocate(self, cpu, mem):
        self.cpu_used += cpu
        self.mem_used += mem

    def release(self, cpu, mem):
        self.cpu_used -= cpu
        self.mem_used -= mem

