        elif e['event'] == 'finish':
            occ[e['machine']]['cpu'] -= e['cpu']
            occ[e['machine']]['mem'] -= e['mem']
            occ[e['machine']]['tasks'].remove(e['task'])
        elif e['event'] in ['evict', 'fail']:
            occ[e['machine']]['cpu'] -= e['cpu']
            occ[e['machine']]['mem'] -= e['mem']
